import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec3, mix, float } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Texture } = ctx.THREE;

  // Aspect ratio from atlas region: 512x320
  const width = 1.6;
  const height = 1.0;

  const geometry = new PlaneGeometry(width, height);

  // Gradient colors from spec: surface (#0b0b10) at bottom, ink (#16161d) at top
  const bottomColor = vec3(0.0431, 0.0431, 0.0627); // #0b0b10
  const topColor = vec3(0.0863, 0.0863, 0.1137);    // #16161d

  // Initial material without texture (gradient only)
  const gradientNode = mix(bottomColor, topColor, uv().y);
  const material = new MeshBasicNodeMaterial({
    colorNode: gradientNode,
    side: 2 // DoubleSide
  });

  const mesh = new Mesh(geometry, material);
  mesh.position.set(0, 0, 0); // position applied by adapter via config.scenePosition
  mesh.rotation.set(0, 0, 0);
  mesh.scale.set(1, 1, 1);

  const group = new Group();
  group.add(mesh);

  // Load brushed metal texture and update material
  const texturePromise = ctx.textureLoader.loadTexture(config.imageUrl);
  texturePromise.then((tex) => {
    // Create a texture node from the loaded texture
    const texNode = texture(tex);
    // Blend texture with gradient (80% texture, 20% gradient for subtle effect)
    const blended = mix(gradientNode, texNode, 0.8);
    material.colorNode = blended;
    material.needsUpdate = true;
  });

  // No event handlers
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    // Kill GSAP timelines (none)
    // Dispose geometry and material
    geometry.dispose();
    material.dispose();
    // The texture will be disposed by the global cache; we don't call dispose here
    // because it might be reused
  };

  return group;
}
